import type { BankQuestion } from "@/lib/bank";

/** Indian National Movement (1885–1947) (History): 111 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"history-national-movement-1","question":"The Indian National Congress was founded in:","options":["1857","1885","1905","1920"],"answer":1,"explanation":"The INC was founded in 1885 by A. O. Hume.","difficulty":"easy"},
  {"id":"history-national-movement-2","question":"The Jallianwala Bagh massacre took place in:","options":["1905","1919","1930","1942"],"answer":1,"explanation":"On 13 April 1919, General Dyer’s troops fired on a peaceful gathering in Amritsar.","difficulty":"easy"},
  {"id":"history-national-movement-3","question":"Who presided over the first session of the Indian National Congress in 1885?","options":["Dadabhai Naoroji","W. C. Bonnerjee","A. O. Hume","Surendranath Banerjee"],"answer":1,"explanation":"W. C. Bonnerjee presided over the first session held in Bombay in December 1885.","difficulty":"moderate"},
  {"id":"history-national-movement-4","question":"The Partition of Bengal (1905) was carried out under which Viceroy?","options":["Lord Ripon","Lord Curzon","Lord Minto","Lord Dalhousie"],"answer":1,"explanation":"Lord Curzon announced the Partition of Bengal in 1905.","difficulty":"moderate"},
  {"id":"history-national-movement-5","question":"The Non-Cooperation Movement was withdrawn after which incident?","options":["Jallianwala Bagh massacre","Chauri Chaura incident","Kakori conspiracy","Partition of Bengal"],"answer":1,"explanation":"After a mob burnt a police station at Chauri Chaura (February 1922), Gandhi called off the movement.","difficulty":"moderate"},
  {"id":"history-national-movement-6","question":"The Dandi March began on:","options":["26 January 1930","12 March 1930","6 April 1930","8 August 1942"],"answer":1,"explanation":"Gandhi started the march from Sabarmati Ashram on 12 March 1930 and broke the salt law at Dandi on 6 April 1930.","difficulty":"hard"},
  {"id":"history-national-movement-7","question":"The Swadeshi Movement was launched in response to the:","options":["Rowlatt Act","Partition of Bengal","Simon Commission","Jallianwala Bagh massacre"],"answer":1,"explanation":"The Swadeshi and Boycott movements began in 1905 against the Partition of Bengal.","difficulty":"hard"},
  {"id":"history-national-movement-8","question":"Where was the first session of the Indian National Congress held?","options":["Calcutta","Bombay","Madras","Poona"],"answer":1,"explanation":"The first session met at Gokuldas Tejpal Sanskrit College, Bombay, in December 1885.","difficulty":"hard"},
  {"id":"history-national-movement-9","question":"The Gandhi–Irwin Pact was signed in:","options":["1929","1931","1932","1935"],"answer":1,"explanation":"The pact (March 1931) ended the Civil Disobedience Movement and led to Gandhi attending the Second Round Table Conference.","difficulty":"very-hard"},
  {"id":"history-national-movement-10","question":"The Simon Commission (1927) was boycotted in India because:","options":["It recommended partition","It had no Indian member","It rejected dominion status","It imposed the Rowlatt Act"],"answer":1,"explanation":"All seven members were British, so Indians protested with the slogan “Simon Go Back”.","difficulty":"very-hard"},
  {"id":"history-national-movement-11","question":"Which session of the Congress adopted the resolution of “Purna Swaraj” (complete independence)?","options":["Lahore, 1929","Karachi, 1931","Calcutta, 1928","Lucknow, 1916"],"answer":0,"explanation":"The Lahore session (December 1929), presided over by Jawaharlal Nehru, declared Purna Swaraj; 26 January 1930 was celebrated as Independence Day.","difficulty":"very-hard"},
  {"id":"history-national-movement-12","question":"The Indian National Congress was founded in 1885 by:","options":["W. C. Bonnerjee","A. O. Hume","Dadabhai Naoroji","Surendranath Banerjee"],"answer":1,"explanation":"A. O. Hume founded the INC; W. C. Bonnerjee presided over its first session in Bombay.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"history-national-movement-13","question":"The Jallianwala Bagh massacre (1919) took place in the city of:","options":["Lahore","Amritsar","Delhi","Jalandhar"],"answer":1,"explanation":"On 13 April 1919 General Dyer fired on a gathering at Jallianwala Bagh, Amritsar.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"history-national-movement-14","question":"The Dandi March of 1930 was launched to protest against the:","options":["Rowlatt Act","Partition of Bengal","Salt tax","Simon Commission"],"answer":2,"explanation":"Gandhi walked from Sabarmati to Dandi (12 March – 6 April 1930) to break the salt law.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"history-national-movement-15","question":"The slogan “Do or Die” is associated with which movement?","options":["Non-Cooperation Movement","Civil Disobedience Movement","Quit India Movement","Swadeshi Movement"],"answer":2,"explanation":"Gandhi gave the call at the Bombay session of the AICC on 8 August 1942.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"history-national-movement-16","question":"Who was the President of the Congress at the Lahore session (1929) where Purna Swaraj was demanded?","options":["Motilal Nehru","Jawaharlal Nehru","Subhas Chandra Bose","Sardar Patel"],"answer":1,"explanation":"Jawaharlal Nehru presided at Lahore; 26 January 1930 was declared Independence Day.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"history-national-movement-17","question":"The Cabinet Mission (1946) consisted of three members. Who among these was NOT one of them?","options":["Lord Pethick-Lawrence","Stafford Cripps","A. V. Alexander","Lord Wavell"],"answer":3,"explanation":"Wavell was the Viceroy; the Mission was Pethick-Lawrence, Cripps and Alexander.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-national-movement-18","question":"Arrange in chronological order: 1. Champaran Satyagraha 2. Kheda Satyagraha 3. Ahmedabad mill strike 4. Rowlatt Satyagraha","options":["1, 2, 3, 4","1, 3, 2, 4","3, 1, 2, 4","2, 1, 3, 4"],"answer":1,"explanation":"Champaran (1917), Ahmedabad mill strike (Feb–Mar 1918), Kheda (from Mar 1918), Rowlatt Satyagraha (1919).","difficulty":"hard"},
  {"id":"history-national-movement-19","question":"The Swaraj Party was founded in 1923 by Motilal Nehru and:","options":["C. R. Das","Bal Gangadhar Tilak","Lala Lajpat Rai","Bipin Chandra Pal"],"answer":0,"explanation":"C. R. Das and Motilal Nehru formed the Swaraj Party to contest council elections.","difficulty":"hard"},
  {"id":"history-national-movement-20","question":"The “August Offer” of 1940 was made by Viceroy:","options":["Lord Linlithgow","Lord Wavell","Lord Irwin","Lord Mountbatten"],"answer":0,"explanation":"Linlithgow offered dominion status as the objective and an expanded Executive Council; Congress rejected it.","difficulty":"very-hard"},
  {"id":"history-national-movement-21","question":"Consider: 1. The Poona Pact (1932) came after Gandhi’s fast in Yerwada jail. 2. It replaced separate electorates for the Depressed Classes with reserved seats in joint electorates. 3. It followed Ramsay MacDonald’s Communal Award. Which are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct; the pact was signed by B. R. Ambedkar and Madan Mohan Malaviya.","difficulty":"very-hard"},
  {"id":"history-national-movement-22","question":"How many of these statements are correct? I. The Congress split at Surat in 1907. II. The All-India Muslim League was founded at Dhaka in 1906. III. The Lucknow Pact of 1916 was between the Congress and the Muslim League. IV. The Partition of Bengal was annulled in 1905.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The partition of 1905 was annulled in 1911.","difficulty":"very-hard"},
  {"id":"history-national-movement-23","question":"How many of these statements are correct? I. The Non-Cooperation Movement was withdrawn after Chauri Chaura. II. The Simon Commission had no Indian member. III. The Congress attended the First Round Table Conference.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. The Congress boycotted the First Round Table Conference (1930–31) and attended only the second.","difficulty":"very-hard"},
  {"id":"history-national-movement-24","question":"Arrange in chronological order: 1. Champaran Satyagraha 2. Rowlatt Satyagraha 3. Kheda Satyagraha 4. Ahmedabad mill strike","options":["1-4-3-2","1-3-4-2","4-1-3-2","1-3-2-4"],"answer":0,"explanation":"Champaran (1917), Ahmedabad mill strike (February–March 1918), Kheda (from March 1918), Rowlatt Satyagraha (1919).","difficulty":"very-hard"},
  {"id":"history-national-movement-25","question":"Who among these was NOT a founder of the Swaraj Party (1923)?","options":["Chittaranjan Das","Motilal Nehru","N. C. Kelkar","Rajendra Prasad"],"answer":3,"explanation":"Rajendra Prasad was a “no-changer” who opposed entering the councils. C. R. Das, Motilal Nehru and Kelkar were “pro-changers” who founded the Swaraj Party.","difficulty":"very-hard"},
  {"id":"history-national-movement-26","question":"Assertion (A): Gandhi withdrew the Non-Cooperation Movement in February 1922. Reason (R): At Chauri Chaura a mob set fire to a police station, killing several policemen.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Gandhi called off the movement because the Chauri Chaura violence (5 February 1922) showed it was turning violent.","difficulty":"very-hard"},
  {"id":"history-national-movement-27","question":"Arrange in chronological order: 1. Dandi March begins 2. Chittagong armoury raid 3. Lahore session adopts Purna Swaraj 4. Gandhi–Irwin Pact","options":["3-1-2-4","3-2-1-4","1-3-2-4","3-1-4-2"],"answer":0,"explanation":"Lahore session (December 1929), Dandi March (12 March 1930), Chittagong raid (18 April 1930), Gandhi–Irwin Pact (5 March 1931).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-national-movement-28","question":"Which pair of Congress session and its president is NOT correctly matched?","options":["Lahore 1929 – Jawaharlal Nehru","Karachi 1931 – Vallabhbhai Patel","Haripura 1938 – Subhas Chandra Bose","Faizpur 1936 – Rajendra Prasad"],"answer":3,"explanation":"Faizpur (1936), the first session held in a village, was presided over by Jawaharlal Nehru. Rajendra Prasad presided at Bombay in 1934.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id": "history-national-movement-29", "question": "The two Home Rule Leagues of 1916 were started by:", "options": ["Motilal Nehru and C. R. Das", "Gopal Krishna Gokhale and Annie Besant", "Tilak and Lala Lajpat Rai", "Bal Gangadhar Tilak and Annie Besant"], "answer": 3, "explanation": "Tilak founded his League at Belgaum in April 1916 and Annie Besant hers at Madras in September 1916, both demanding self-government within the Empire.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-national-movement-30", "question": "The Quit India resolution was passed by the Congress on 8 August 1942 at:", "options": ["Calcutta", "Bombay", "Delhi", "Wardha"], "answer": 1, "explanation": "The All India Congress Committee met at Gowalia Tank maidan, Bombay, where Gandhi gave the call “Do or Die”; the Wardha working committee had drafted the resolution in July.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-national-movement-31", "question": "The Rowlatt Act, which allowed detention without trial, was passed in:", "options": ["1917", "1919", "1921", "1915"], "answer": 1, "explanation": "The Anarchical and Revolutionary Crimes Act (Rowlatt Act) of March 1919 provoked the Rowlatt Satyagraha, Gandhi’s first all-India movement, and led to the Jallianwala Bagh tragedy.", "difficulty": "easy", "source": "SSC CHSL · UPSSSC PET"},
  {"id": "history-national-movement-32", "question": "The Congress session of 1916 at which the Moderates and Extremists reunited, and the Congress–League Pact was signed, was presided over by:", "options": ["Ambica Charan Mazumdar", "Annie Besant", "Bal Gangadhar Tilak", "Rash Behari Ghosh"], "answer": 0, "explanation": "The Lucknow session (1916) under Ambica Charan Mazumdar readmitted Tilak’s group nine years after the Surat split. Annie Besant presided the next year at Calcutta.", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-national-movement-33", "question": "The Khilafat movement (1919–24) was led in India chiefly by:", "options": ["Jinnah and Liaquat Ali Khan", "Sir Syed Ahmad Khan and Aga Khan", "The Ali brothers, Maulana Mohammad Ali and Shaukat Ali", "Maulana Azad and Hakim Ajmal Khan only"], "answer": 2, "explanation": "The Ali brothers, with Maulana Azad, Hakim Ajmal Khan and Hasrat Mohani, led the Khilafat agitation, which Gandhi merged with Non-Cooperation in 1920.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "history-national-movement-34", "question": "Mahatma Gandhi returned permanently to India from South Africa on:", "options": ["9 January 1916", "26 January 1915", "12 March 1915", "9 January 1915"], "answer": 3, "explanation": "Gandhi landed at Bombay on 9 January 1915; the date is now observed as Pravasi Bharatiya Diwas.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-national-movement-35", "question": "The Kakori train action of 1925, in which revolutionaries looted a government treasury, was led by:", "options": ["Bhagat Singh", "Ram Prasad Bismil", "Surya Sen", "Chandrashekhar Azad only"], "answer": 1, "explanation": "Ram Prasad Bismil planned the Kakori action with Ashfaqullah Khan, Rajendra Lahiri and Roshan Singh, all four of whom were hanged in 1927; Chandrashekhar Azad escaped.", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-national-movement-36", "question": "The Hindustan Socialist Republican Association was formed in September 1928 at:", "options": ["Kanpur", "Lahore", "Feroz Shah Kotla, Delhi", "Calcutta"], "answer": 2, "explanation": "Revolutionaries including Bhagat Singh, Chandrashekhar Azad and Sukhdev met at Feroz Shah Kotla and renamed the Hindustan Republican Association as the HSRA, adding “Socialist” to its goal.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "history-national-movement-37", "question": "The Bardoli Satyagraha of 1928 against enhanced land revenue was led by:", "options": ["Mahatma Gandhi", "Vallabhbhai Patel", "Vinoba Bhave", "Morarji Desai"], "answer": 1, "explanation": "Vallabhbhai Patel led the peasants of Bardoli (Gujarat), forcing an inquiry and reduction of the revenue; the women of Bardoli gave him the title “Sardar”.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-national-movement-38", "question": "Separate electorates for Muslims were first introduced by the:", "options": ["Indian Councils Act, 1892", "Indian Councils Act, 1909", "Government of India Act, 1919", "Government of India Act, 1935"], "answer": 1, "explanation": "The Morley–Minto Reforms (Indian Councils Act, 1909) introduced separate electorates for Muslims; the 1919 Act extended them to Sikhs, Indian Christians, Anglo-Indians and Europeans.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-39", "question": "In the Individual Satyagraha launched by Gandhi in October 1940, the first satyagrahi was:", "options": ["Jawaharlal Nehru", "Vinoba Bhave", "Brahma Datt", "Sardar Patel"], "answer": 1, "explanation": "Vinoba Bhave was chosen as the first satyagrahi (17 October 1940), Jawaharlal Nehru the second and Brahma Datt the third; the aim was to protest against India’s involvement in the war without consent.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-40", "question": "The Cripps Mission (March 1942) proposed:", "options": ["Immediate independence for India", "Provincial autonomy under a federal centre", "Partition of India into two dominions", "Dominion status after the war and a constitution-making body elected by provincial legislatures, with provinces free to opt out"], "answer": 3, "explanation": "Cripps offered dominion status after the war with a constituent assembly, but allowed provinces to stay out of the Union, which Congress and the League both rejected.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "history-national-movement-41", "question": "The Partition of Bengal was annulled and the capital shifted from Calcutta to Delhi during the viceroyalty of:", "options": ["Lord Minto II", "Lord Hardinge II", "Lord Chelmsford", "Lord Curzon"], "answer": 1, "explanation": "Both decisions were announced at the Delhi Durbar of December 1911 under Lord Hardinge II; a bomb was thrown at him in Delhi in 1912.", "difficulty": "hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-national-movement-42", "question": "The Ghadar Party, which planned an armed uprising in India during the First World War, was founded in 1913 at:", "options": ["Berlin", "Vancouver", "San Francisco", "Tokyo"], "answer": 2, "explanation": "Punjabi immigrants led by Lala Har Dayal, with Sohan Singh Bhakna as president, founded the Ghadar Party at San Francisco and published the paper “Ghadar”.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-43", "question": "The Shimla Conference of June–July 1945, called to discuss the Wavell Plan, broke down mainly because:", "options": ["The Congress refused to attend", "The Muslim League insisted that only it could nominate all the Muslim members of the Executive Council", "The British withdrew the plan after the Labour victory", "Gandhi demanded immediate independence"], "answer": 1, "explanation": "Jinnah claimed the League’s exclusive right to name Muslim members, which the Congress (with Maulana Azad as its president) could not accept, and Wavell abandoned the plan.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "history-national-movement-44", "question": "Tilak founded his Home Rule League in April 1916 at:", "options": ["Poona", "Belgaum", "Madras", "Bombay"], "answer": 1, "explanation": "Tilak’s League was set up at Belgaum for Maharashtra (excluding Bombay city), Karnataka, the Central Provinces and Berar; Besant’s League, founded at Madras, covered the rest of India.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "history-national-movement-45", "question": "Subhas Chandra Bose proclaimed the Provisional Government of Azad Hind (Free India) on 21 October 1943 at:", "options": ["Rangoon", "Singapore", "Tokyo", "Berlin"], "answer": 1, "explanation": "The Azad Hind Government was proclaimed at Singapore; it declared war on Britain and the USA and was recognised by Japan, Germany and other Axis powers. The Andaman islands were symbolically handed to it.", "difficulty": "hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-national-movement-46", "question": "The “C. R. Formula” of 1944, which accepted the League’s demand for a plebiscite in Muslim-majority areas, was proposed by:", "options": ["C. Rajagopalachari", "Rajendra Prasad", "C. R. Das", "Bhulabhai Desai"], "answer": 0, "explanation": "Rajagopalachari’s formula became the basis of the Gandhi–Jinnah talks of September 1944, which failed because Jinnah wanted Pakistan before independence.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "history-national-movement-47", "question": "Arrange in chronological order: 1. Cabinet Mission 2. Wavell Plan 3. Cripps Mission 4. August Offer", "options": ["4, 3, 2, 1", "3, 4, 2, 1", "4, 3, 1, 2", "3, 4, 1, 2"], "answer": 0, "explanation": "August Offer (1940), Cripps Mission (1942), Wavell Plan (1945) and Cabinet Mission (1946).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-48", "question": "How many of these statements about the Civil Disobedience Movement are correct? I. Gandhi walked from Sabarmati to Dandi in 24 days. II. In Tamil Nadu, C. Rajagopalachari led a salt march from Trichinopoly to Vedaranyam. III. In Malabar, K. Kelappan led a march from Calicut to Payyanur. IV. In Peshawar, Khan Abdul Ghaffar Khan’s Khudai Khidmatgars were active and Garhwali soldiers refused to fire on the crowd.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The march of 12 March to 5 April 1930 covered about 240 miles, and the regional marches and the Garhwali soldiers’ refusal (under Chandra Singh Garhwali) were landmarks of the movement.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-national-movement-49", "question": "Which pair of Gandhian satyagraha and its issue is NOT correctly matched?", "options": ["Champaran 1917 – tinkathia system of indigo cultivation", "Kheda 1918 – demand for remission of land revenue after crop failure", "Ahmedabad 1918 – plague bonus dispute of mill workers", "Bardoli 1928 – led personally by Gandhi"], "answer": 3, "explanation": "Bardoli (1928) was led by Vallabhbhai Patel. The other three were Gandhi’s first struggles in India.", "difficulty": "very-hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-national-movement-50", "question": "Assertion (A): The Congress boycotted the First Round Table Conference in London (1930). Reason (R): The Civil Disobedience Movement was in progress and most Congress leaders were in jail.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The Congress attended only the Second Round Table Conference (1931) after the Gandhi–Irwin Pact released prisoners and suspended the movement.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-51", "question": "How many of these statements about the early Congress are correct? I. A. O. Hume was a retired ICS officer. II. The first session was held at Gokuldas Tejpal Sanskrit College, Bombay, with 72 delegates. III. Dadabhai Naoroji presided over the Congress three times. IV. The first woman president of the Congress was Sarojini Naidu.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct (Naoroji presided in 1886, 1893 and 1906). Annie Besant (1917) was the first woman president; Sarojini Naidu (1925) was the first Indian woman.", "difficulty": "very-hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-national-movement-52", "question": "Arrange these revolutionary actions in chronological order: 1. Kakori train action 2. Chittagong armoury raid 3. Bomb thrown in the Central Legislative Assembly 4. Killing of Saunders at Lahore", "options": ["1, 4, 3, 2", "1, 3, 4, 2", "4, 1, 3, 2", "1, 4, 2, 3"], "answer": 0, "explanation": "Kakori (August 1925), Saunders killed (December 1928), Assembly bomb (April 1929) and Chittagong raid (April 1930).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-53", "question": "How many of these statements about the Quit India Movement are correct? I. The resolution was passed at Bombay on 8 August 1942. II. Gandhi was detained at the Aga Khan Palace in Poona. III. Parallel governments were set up at Ballia, Tamluk and Satara. IV. The Muslim League supported the movement.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The Muslim League, the Communist Party and the Hindu Mahasabha stayed away from Quit India.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-national-movement-54", "question": "Which of the following was NOT a feature of the Mountbatten Plan or the Indian Independence Act, 1947?", "options": ["Division of Bengal and Punjab if their legislatures so voted", "A referendum in the North-West Frontier Province", "Freedom for princely states to join either dominion", "Transfer of power on 26 January 1948"], "answer": 3, "explanation": "Power was transferred on 15 August 1947, much earlier than the June 1948 date Attlee had announced; 26 January was later chosen as Republic Day to honour the 1930 Purna Swaraj pledge.", "difficulty": "very-hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-national-movement-55", "question": "How many of these statements about the Lucknow Pact are correct? I. The Congress accepted separate electorates for Muslims. II. Tilak and Jinnah were its key architects. III. It was signed in 1916 at Lucknow. IV. It was repudiated by the Congress at the Surat session.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The Surat session was in 1907, nine years before the Pact; the pact lost its relevance after 1920 but was never repudiated at Surat.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-56", "question": "Assertion (A): The Khilafat movement lost its purpose by 1924. Reason (R): Mustafa Kemal abolished the office of the Caliph in Turkey in March 1924.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The movement sought to protect the Ottoman Caliph; once Turkey itself abolished the Caliphate, the agitation collapsed.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-national-movement-57", "question": "How many of these statements about the Government of India Act, 1935 are correct? I. It introduced provincial autonomy and abolished dyarchy in the provinces. II. It provided for dyarchy at the centre. III. The proposed All-India Federation never came into being. IV. It abolished separate electorates.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The Act extended separate electorates further, to the depressed classes, women and labour, following the Communal Award.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-58", "question": "Arrange in chronological order: 1. Lucknow Pact 2. Morley–Minto Reforms 3. Rowlatt Act 4. Surat split of the Congress", "options": ["4, 2, 1, 3", "2, 4, 1, 3", "4, 1, 2, 3", "2, 1, 4, 3"], "answer": 0, "explanation": "Surat split (1907), Morley–Minto Reforms (1909), Lucknow Pact (1916) and Rowlatt Act (1919).", "difficulty": "very-hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-national-movement-59", "question": "The slogan “Give me blood, and I will give you freedom” is associated with:", "options": ["Bhagat Singh", "Subhas Chandra Bose", "Bal Gangadhar Tilak", "Lala Lajpat Rai"], "answer": 1, "explanation": "Subhas Chandra Bose gave this call to the Indian National Army in 1944. Tilak’s slogan was “Swaraj is my birthright”.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-national-movement-60", "question": "The Servants of India Society was founded in 1905 by:", "options": ["Gopal Krishna Gokhale", "Dadabhai Naoroji", "Mahadev Govind Ranade", "Pherozeshah Mehta"], "answer": 0, "explanation": "Gokhale founded the Servants of India Society at Poona in 1905 to train dedicated workers for national service.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-national-movement-61", "question": "The British journalist Valentine Chirol called which leader the “father of Indian unrest”?", "options": ["Aurobindo Ghosh", "Lala Lajpat Rai", "Bal Gangadhar Tilak", "Bipin Chandra Pal"], "answer": 2, "explanation": "Chirol used the phrase for Tilak in his book Indian Unrest (1910). Tilak sued him for libel in London and lost.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-62", "question": "The Vaikom Satyagraha (1924–25) in Travancore was launched against:", "options": ["The salt tax", "Forced cultivation of indigo", "Enhanced land revenue", "The ban on lower castes using roads near the Vaikom temple"], "answer": 3, "explanation": "Led by T. K. Madhavan, K. P. Kesava Menon and others, with support from Gandhi and E. V. Ramasamy, it demanded access for avarnas to the roads around the Vaikom temple.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "history-national-movement-63", "question": "The Indian Association, an important pre-Congress political body, was founded in Calcutta in 1876 by:", "options": ["Surendranath Banerjea and Ananda Mohan Bose", "Dadabhai Naoroji and W. C. Bonnerjee", "Pherozeshah Mehta and K. T. Telang", "Sisir Kumar Ghosh and Motilal Ghosh"], "answer": 0, "explanation": "Surendranath Banerjea and Ananda Mohan Bose founded the Indian Association in 1876; it later merged with the Congress.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-64", "question": "The “drain theory”, holding that British rule was draining India’s wealth, was set out in “Poverty and Un-British Rule in India” by:", "options": ["R. C. Dutt", "Dadabhai Naoroji", "M. G. Ranade", "G. V. Joshi"], "answer": 1, "explanation": "Dadabhai Naoroji expounded the drain of wealth in this book (1901). R. C. Dutt developed the theme in his Economic History of India.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-national-movement-65", "question": "The three INA officers tried together at the Red Fort in 1945, sparking nationwide protests, were:", "options": ["Mohan Singh, Rash Behari Bose and Lakshmi Swaminathan", "Shah Nawaz Khan, Prem Kumar Sahgal and Gurbaksh Singh Dhillon", "Habibur Rahman, Mohan Singh and Abid Hasan", "Shah Nawaz Khan, Mohan Singh and Lakshmi Swaminathan"], "answer": 1, "explanation": "The first Red Fort trial involved a Muslim, a Hindu and a Sikh officer, which united public opinion. Bhulabhai Desai led the defence, joined by Nehru and others.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-66", "question": "The Royal Indian Navy mutiny of February 1946 began among ratings of:", "options": ["HMIS Talwar at Bombay", "HMIS Hindustan at Karachi", "HMIS Kathiawar at Calcutta", "HMIS Delhi at Madras"], "answer": 0, "explanation": "The revolt started on 18 February 1946 on the signals training establishment HMIS Talwar in Bombay over food and racial discrimination, and spread to other ports.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-67", "question": "The Montagu Declaration of August 1917 announced that British policy in India aimed at:", "options": ["Immediate dominion status", "Separate electorates for all communities", "The gradual development of self-governing institutions leading to responsible government", "Complete independence after the war"], "answer": 2, "explanation": "Secretary of State Edwin Montagu declared the goal of increasing association of Indians in administration and the progressive realisation of responsible government; it led to the 1919 Act.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-68", "question": "The government committee that inquired into the Jallianwala Bagh massacre and the Punjab disturbances of 1919 was headed by:", "options": ["Lord Hunter", "Sir John Simon", "Sir Stafford Cripps", "Sir Michael O’Dwyer"], "answer": 0, "explanation": "The Disorders Inquiry (Hunter) Committee was set up in October 1919. The Congress ran its own inquiry. O’Dwyer was the Lieutenant-Governor of Punjab at the time.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-69", "question": "M. A. Jinnah put forward his “Fourteen Points” in March 1929 in response to the:", "options": ["Simon Commission", "Communal Award", "Nehru Report", "Cripps proposals"], "answer": 2, "explanation": "The Nehru Report (August 1928) rejected separate electorates and proposed dominion status. Jinnah’s Fourteen Points answered it with demands for Muslim safeguards.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "history-national-movement-70", "question": "The Cripps proposals of 1942 were famously described as “a post-dated cheque” by:", "options": ["Jawaharlal Nehru", "Mahatma Gandhi", "Subhas Chandra Bose", "Maulana Azad"], "answer": 1, "explanation": "Gandhi is credited with calling the offer a post-dated cheque, since its key promise (dominion status) was for after the war; “on a crashing bank” was a later addition by others.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-national-movement-71", "question": "At the All India Congress Committee session in Bombay on 8 August 1942, the Quit India resolution was moved by:", "options": ["Mahatma Gandhi", "Vallabhbhai Patel", "Maulana Azad", "Jawaharlal Nehru"], "answer": 3, "explanation": "Nehru moved the resolution and Patel seconded it; Gandhi then gave his “Do or Die” speech at Gowalia Tank Maidan.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "history-national-movement-72", "question": "Who was the Viceroy of India when the Indian National Congress was founded in 1885?", "options": ["Lord Ripon", "Lord Lansdowne", "Lord Dufferin", "Lord Lytton"], "answer": 2, "explanation": "Lord Dufferin (1884–88) was Viceroy in December 1885. Ripon had left in 1884; Lansdowne came in 1888.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-national-movement-73", "question": "Arrange in chronological order: 1. Montagu Declaration 2. Lucknow Pact 3. Jallianwala Bagh massacre 4. Nehru Report", "options": ["1, 2, 3, 4", "2, 1, 3, 4", "2, 3, 1, 4", "2, 1, 4, 3"], "answer": 1, "explanation": "Lucknow Pact: December 1916. Montagu Declaration: August 1917. Jallianwala Bagh: April 1919. Nehru Report: August 1928.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-74", "question": "Match the newspaper with its founder or editor: A. Kesari B. Young India C. Al-Hilal D. Mooknayak. 1. B. R. Ambedkar 2. Maulana Abul Kalam Azad 3. M. K. Gandhi 4. B. G. Tilak", "options": ["A-4, B-3, C-2, D-1", "A-4, B-2, C-3, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "Kesari (Marathi): Tilak. Young India: edited by Gandhi from 1919. Al-Hilal (Urdu, 1912): Azad. Mooknayak (Marathi, 1920): Ambedkar.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-75", "question": "Assertion (A): The Congress ministries in the provinces resigned in October–November 1939. Reason (R): The Viceroy had declared India a belligerent in the Second World War without consulting Indian leaders.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Linlithgow’s declaration of 3 September 1939 and Britain’s refusal to state its war aims for India led the Congress ministries to resign.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-76", "question": "How many of these statements about the Indian National Army are correct? I. It was first organised by Captain Mohan Singh with Japanese help. II. Rash Behari Bose handed over its leadership to Subhas Chandra Bose in Singapore in 1943. III. Its women’s unit, the Rani Jhansi Regiment, was led by Lakshmi Swaminathan. IV. The INA flag was hoisted on Indian soil at Moirang in Manipur in 1944.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Moirang, near Imphal, saw the INA tricolour raised in April 1944 during the Imphal–Kohima campaign.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-77", "question": "Arrange in chronological order: 1. Desai–Liaquat Pact 2. Individual Satyagraha 3. C. R. Formula 4. Cripps Mission", "options": ["2, 4, 1, 3", "4, 2, 3, 1", "2, 3, 4, 1", "2, 4, 3, 1"], "answer": 3, "explanation": "Individual Satyagraha: October 1940. Cripps Mission: March 1942. C. R. Formula: 1944. Desai–Liaquat Pact: January 1945.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-78", "question": "How many of these statements about the Moderates are correct? I. They believed in constitutional methods such as petitions and resolutions. II. Gokhale, whom Gandhi regarded as his political guru, was a Moderate. III. Pherozeshah Mehta was a Moderate leader. IV. Lala Lajpat Rai was a leading Moderate.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: Lajpat Rai, with Tilak and Bipin Chandra Pal (Lal–Bal–Pal), led the Extremists.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-79", "question": "Who among the following did NOT attend the First Round Table Conference (1930–31)?", "options": ["B. R. Ambedkar", "Tej Bahadur Sapru", "M. K. Gandhi", "M. A. Jinnah"], "answer": 2, "explanation": "Gandhi attended only the Second Round Table Conference (1931), as the sole Congress representative. Ambedkar, Sapru and Jinnah were at the first.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-80", "question": "Assertion (A): The Simon Commission was appointed in 1927, about two years before the date contemplated by law. Reason (R): The Government of India Act, 1919 provided for a commission to review its working after ten years.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 1, "explanation": "Both are true, but R does not explain A. R explains why a commission was due at all; it was appointed early because the Conservative government feared that a Labour government might pick the commission instead.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-81", "question": "Match the revolutionary organisation with its founder: A. Hindustan Republican Association (1924) B. Abhinav Bharat (1904) C. Anushilan Samiti (Calcutta, 1902) D. Ghadar Party (1913). 1. Lala Har Dayal and Sohan Singh Bhakna 2. V. D. Savarkar and his brother 3. Pramathanath Mitra 4. Sachindranath Sanyal", "options": ["A-4, B-3, C-2, D-1", "A-4, B-2, C-3, D-1", "A-2, B-4, C-3, D-1", "A-4, B-2, C-1, D-3"], "answer": 1, "explanation": "The HRA was founded by Sachindranath Sanyal (with Bismil and others); Abhinav Bharat by the Savarkar brothers; the Calcutta Anushilan Samiti by Pramathanath Mitra; the Ghadar Party at San Francisco by Har Dayal and Sohan Singh Bhakna.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-82", "question": "How many of these statements about the Government of India Act, 1919 are correct? I. It introduced dyarchy in the provinces. II. It made the central legislature bicameral. III. It extended communal representation to Sikhs, Indian Christians and Anglo-Indians. IV. It provided for a Public Service Commission, set up in 1926.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The Act divided provincial subjects into transferred and reserved, created the Council of State and Legislative Assembly, extended separate electorates and led to the Central Public Service Commission (1926).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-83", "question": "How many of these statements about the Swadeshi movement are correct? I. It was formally proclaimed at the Calcutta Town Hall on 7 August 1905. II. The day the partition took effect, 16 October 1905, was observed as a day of mourning. III. Rabindranath Tagore wrote “Amar Sonar Bangla” during the agitation. IV. The movement remained confined to Bengal with no echo elsewhere.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: the movement spread to Maharashtra under Tilak, Punjab under Lajpat Rai and Ajit Singh, Delhi and Madras under V. O. Chidambaram Pillai and others.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-84", "question": "Who unfurled an early version of the Indian national flag at the International Socialist Congress in Stuttgart in 1907?", "options": ["Annie Besant", "Bhikaiji Cama", "Sarojini Naidu", "Sister Nivedita"], "answer": 1, "explanation": "Madame Bhikaiji Cama raised the flag at Stuttgart in August 1907. She worked with the revolutionaries of India House and the Paris Indian Society.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-national-movement-85", "question": "Who was popularly called the \"Frontier Gandhi\"?", "options": ["Maulana Abul Kalam Azad", "Khan Abdul Ghaffar Khan", "Hakim Ajmal Khan", "Mohammad Ali Jauhar"], "answer": 1, "explanation": "Khan Abdul Ghaffar Khan of the North-West Frontier Province founded the Khudai Khidmatgars, or Red Shirts, a non-violent Pathan movement, and was a close associate of Gandhi.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-national-movement-86", "question": "Which leader died in 1928 from injuries received in a police lathi charge while leading a protest against the Simon Commission at Lahore?", "options": ["Lala Lajpat Rai", "Bhagat Singh", "Motilal Nehru", "Bipin Chandra Pal"], "answer": 0, "explanation": "Lala Lajpat Rai, the \"Punjab Kesari\", was hit in a lathi charge ordered by J. A. Scott and died on 17 November 1928. Bhagat Singh and his comrades took revenge by killing J. P. Saunders in December 1928.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-national-movement-87", "question": "Who was the first Muslim president of the Indian National Congress?", "options": ["Rahimtullah Sayani", "Maulana Azad", "Badruddin Tyabji", "M. A. Ansari"], "answer": 2, "explanation": "Badruddin Tyabji presided over the third session at Madras in 1887. Rahimtullah Sayani presided in 1896, and Maulana Azad in 1923 and 1940–46.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-88", "question": "The Nehru Report (1928), drafted by a committee headed by Motilal Nehru, demanded:", "options": ["Complete independence", "Dominion status for India", "Separate electorates for all minorities", "A federation that excluded the princely States"], "answer": 1, "explanation": "The Nehru Report asked for dominion status, joint electorates with seats reserved for minorities, and a list of fundamental rights. Younger leaders such as Jawaharlal Nehru and Subhas Bose pushed for complete independence, which Lahore adopted in 1929.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-89", "question": "Who invited Gandhi to look into the grievances of indigo cultivators in Champaran?", "options": ["Rajendra Prasad", "J. B. Kripalani", "Mazharul Haq", "Raj Kumar Shukla"], "answer": 3, "explanation": "Raj Kumar Shukla, a cultivator from Champaran, met Gandhi at the Lucknow Congress of 1916 and persuaded him to come. Rajendra Prasad and J. B. Kripalani joined Gandhi there in 1917.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-90", "question": "The slogan \"Inquilab Zindabad\" is usually credited to:", "options": ["Bhagat Singh", "Muhammad Iqbal", "Chandrashekhar Azad", "Maulana Hasrat Mohani"], "answer": 3, "explanation": "Maulana Hasrat Mohani is credited with coining \"Inquilab Zindabad\" in 1921. Bhagat Singh and his comrades made it famous when they shouted it in the Central Legislative Assembly in 1929.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-91", "question": "The Komagata Maru, whose Indian passengers were turned back in 1914, had sailed to:", "options": ["San Francisco, USA", "Durban, South Africa", "Vancouver, Canada", "Singapore"], "answer": 2, "explanation": "The Japanese ship carried Punjabi emigrants to Vancouver, where Canada refused them entry. On its return to Budge Budge near Calcutta, police firing killed several passengers, which angered the Ghadar movement.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-92", "question": "Matangini Hazra, a woman in her seventies who was shot while leading a Quit India procession in 1942, was killed at:", "options": ["Ballia", "Tamluk", "Satara", "Chittagong"], "answer": 1, "explanation": "Matangini Hazra fell at Tamluk in Midnapore district, Bengal, where a parallel government (the Tamralipta Jatiya Sarkar) was later set up. Ballia and Satara also had parallel governments.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-93", "question": "The Indian Independence Act, 1947 received the royal assent on:", "options": ["18 July 1947", "3 June 1947", "14 August 1947", "15 August 1947"], "answer": 0, "explanation": "The Act received the royal assent on 18 July 1947 and fixed 15 August 1947 as the appointed day. The Mountbatten Plan was announced on 3 June 1947.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-94", "question": "The Muzaffarpur bomb attack of April 1908, aimed at the judge Kingsford but killing two Englishwomen, was carried out by:", "options": ["Bhagat Singh and Batukeshwar Dutt", "Rash Behari Bose and Basant Kumar Biswas", "Surya Sen and Ganesh Ghosh", "Khudiram Bose and Prafulla Chaki"], "answer": 3, "explanation": "Khudiram Bose was hanged, and Prafulla Chaki shot himself to avoid arrest. The attack led to the Alipore conspiracy case against Aurobindo Ghose and others. Rash Behari Bose was behind the 1912 bomb thrown at Lord Hardinge.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-95", "question": "Gandhi returned his Kaisar-i-Hind medal to the British government in August 1920 in protest against:", "options": ["The Punjab wrongs and the Khilafat issue", "The partition of Bengal", "The Simon Commission", "The Communal Award"], "answer": 0, "explanation": "Gandhi gave up the medal, awarded for his ambulance work in South Africa, as the Non-Cooperation and Khilafat movement began over the Jallianwala Bagh massacre, the Punjab wrongs and the treatment of Turkey.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-national-movement-96", "question": "The All India Trade Union Congress, founded in Bombay in 1920, had as its first president:", "options": ["N. M. Joshi", "Lala Lajpat Rai", "S. A. Dange", "V. V. Giri"], "answer": 1, "explanation": "Lala Lajpat Rai presided over the founding session of the AITUC in October 1920, and N. M. Joshi was one of its organisers. S. A. Dange was among those later tried in the Meerut conspiracy case.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-97", "question": "The All India Kisan Sabha was formed at Lucknow in 1936 with which leader as its president?", "options": ["N. G. Ranga", "Baba Ramchandra", "Swami Sahajanand Saraswati", "Indulal Yagnik"], "answer": 2, "explanation": "Swami Sahajanand Saraswati of Bihar was its first president, and N. G. Ranga was general secretary. Baba Ramchandra had led the Awadh kisan movement in 1920–21.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-national-movement-98", "question": "After Gandhi's arrest in May 1930, who led the satyagraha at the Dharasana salt works, where police beat the volunteers brutally?", "options": ["Sarojini Naidu", "Kasturba Gandhi", "Aruna Asaf Ali", "Kamaladevi Chattopadhyay"], "answer": 0, "explanation": "Sarojini Naidu led the Dharasana raid with Imam Sahib and Manilal Gandhi. The American journalist Webb Miller's report of the beatings drew world attention.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-99", "question": "During the Quit India Movement, who ran the secret \"Congress Radio\" from Bombay?", "options": ["Aruna Asaf Ali", "Usha Mehta", "Sucheta Kripalani", "Kanaklata Barua"], "answer": 1, "explanation": "Usha Mehta, then a young student, ran the underground Congress Radio from August to November 1942, when it was found and she was jailed. Aruna Asaf Ali hoisted the flag at Gowalia Tank on 9 August 1942.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-100", "question": "The Nankana Sahib massacre of February 1921, in which reformers were killed at a gurdwara, was connected with:", "options": ["The Ghadar movement", "The Kuka movement", "The Singh Sabha movement of the 1870s", "The Akali (Gurdwara Reform) movement"], "answer": 3, "explanation": "Reformers who wanted to free the gurdwaras from corrupt mahants were killed at Nankana Sahib. The Akali movement led to the Sikh Gurdwaras Act of 1925, which placed shrines under the SGPC. The Kukas were active in the 1860s and 1870s.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-national-movement-101", "question": "Who shot Sir Michael O'Dwyer, Lieutenant-Governor of Punjab at the time of the Jallianwala Bagh massacre, in London in March 1940?", "options": ["Madan Lal Dhingra", "Bhagat Singh", "Udham Singh", "Kartar Singh Sarabha"], "answer": 2, "explanation": "Udham Singh shot O'Dwyer at Caxton Hall on 13 March 1940 and was hanged in July 1940. Madan Lal Dhingra had killed Curzon Wyllie in London in 1909.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-102", "question": "Match the Congress session with its president: A. Calcutta, 1906 B. Surat, 1907 C. Belgaum, 1924 D. Meerut, 1946. 1. J. B. Kripalani 2. M. K. Gandhi 3. Rash Behari Ghosh 4. Dadabhai Naoroji", "options": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Dadabhai Naoroji presided at Calcutta in 1906 and spoke of Swaraj. Rash Behari Ghosh presided at Surat in 1907, where the party split. Belgaum (1924) was the only session Gandhi presided over, and Kripalani presided at Meerut in 1946.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-103", "question": "Arrange these events of 1946 in chronological order: 1. Direct Action Day called by the Muslim League 2. Formation of the Interim Government 3. Royal Indian Navy mutiny 4. Arrival of the Cabinet Mission", "options": ["3, 4, 1, 2", "4, 3, 1, 2", "3, 4, 2, 1", "3, 1, 4, 2"], "answer": 0, "explanation": "RIN mutiny (18 February) → Cabinet Mission arrives (24 March) → Direct Action Day (16 August) → Interim Government headed by Nehru (2 September 1946).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-104", "question": "How many of these statements about the Round Table Conferences are correct? I. B. R. Ambedkar attended all three. II. Tej Bahadur Sapru attended all three. III. The Congress stayed away from the third. IV. The third conference was held in late 1932.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The Congress attended only the second conference (1931), through Gandhi. The third (November–December 1932) was small, and its work fed into the White Paper of 1933 and the Act of 1935.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-105", "question": "Assertion (A): The Muslim League observed 22 December 1939 as a \"Day of Deliverance\". Reason (R): The Congress ministries had resigned in protest against India being made a party to the Second World War without its consent.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Jinnah called on Muslims to celebrate deliverance from Congress rule after the Congress ministries resigned in October–November 1939. So the resignation in R is what prompted A.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-106", "question": "Match the peasant movement with its region and feature: A. Eka movement B. Tebhaga movement C. Moplah rebellion D. Telangana movement. 1. Malabar, 1921 2. Awadh, 1921–22, led by Madari Pasi 3. Bengal, 1946–47, sharecroppers demanding two-thirds of the crop 4. Hyderabad State, 1946–51, armed struggle against landlords and the Nizam", "options": ["A-2, B-1, C-3, D-4", "A-2, B-3, C-1, D-4", "A-2, B-3, C-4, D-1", "A-3, B-2, C-1, D-4"], "answer": 1, "explanation": "Eka (unity) in Awadh was led by Madari Pasi. In the Tebhaga movement, Bengal sharecroppers (bargadars) demanded two-thirds of the crop. The Moplah rising was in Malabar in 1921, and the communist-led Telangana struggle lasted from 1946 to 1951.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-107", "question": "How many of these statements about the Lahore Resolution of the Muslim League are correct? I. It was adopted in March 1940. II. It did not use the word \"Pakistan\". III. The name \"Pakistan\" had been coined in 1933 by Choudhary Rahmat Ali. IV. It was adopted at the League's Karachi session.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The resolution, moved by A. K. Fazlul Huq at the Lahore session presided over by Jinnah, asked for \"independent states\" in the Muslim-majority areas. The press soon called it the Pakistan Resolution.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-108", "question": "Match the Viceroy with an event of his tenure: A. Lord Reading B. Lord Irwin C. Lord Willingdon D. Lord Chelmsford. 1. Jallianwala Bagh massacre 2. Chauri Chaura incident 3. Dandi March 4. Communal Award and Poona Pact", "options": ["A-3, B-2, C-4, D-1", "A-2, B-4, C-3, D-1", "A-2, B-3, C-4, D-1", "A-2, B-3, C-1, D-4"], "answer": 2, "explanation": "Chelmsford (1916–21): Rowlatt Act and Jallianwala Bagh. Reading (1921–26): Chauri Chaura and the Moplah rising. Irwin (1926–31): Simon Commission and Dandi. Willingdon (1931–36): Communal Award and Poona Pact (1932).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-109", "question": "How many of these statements about India House in London are correct? I. It was founded in 1905 by Shyamji Krishna Varma. II. V. D. Savarkar lived there while studying law. III. Madan Lal Dhingra, who shot Curzon Wyllie in 1909, was linked to it. IV. Its circle published the journal \"The Indian Sociologist\".", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. India House in Highgate was a hostel and a centre for revolutionaries. After Dhingra's act in 1909 the British cracked down, and Krishna Varma moved to Paris.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-110", "question": "How many of these statements about the Karachi session of the Congress (March 1931) are correct? I. It was presided over by Vallabhbhai Patel. II. It endorsed the Gandhi–Irwin Pact. III. It adopted resolutions on Fundamental Rights and a National Economic Programme. IV. It was the session that first demanded Purna Swaraj.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The session met days after Bhagat Singh, Sukhdev and Rajguru were hanged (23 March 1931). Purna Swaraj had been adopted at Lahore in 1929.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-111", "question": "Assertion (A): Subhas Chandra Bose resigned as Congress president in April 1939, though he had won the presidential election at Tripuri. Reason (R): Gandhi had treated the defeat of his candidate Pattabhi Sitaramayya as his own, and Bose could not form a Working Committee that the Gandhian majority would accept.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "After the Pant resolution asked Bose to form the Working Committee according to Gandhi's wishes, the deadlock led him to resign. Rajendra Prasad succeeded him, and Bose formed the Forward Bloc in May 1939.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-112", "question": "Which leader is NOT correctly matched with the popular title?", "options": ["Deshbandhu – C. R. Das", "Punjab Kesari – Lala Lajpat Rai", "Lokmanya – Bal Gangadhar Tilak", "Grand Old Man of India – Gopal Krishna Gokhale"], "answer": 3, "explanation": "The \"Grand Old Man of India\" was Dadabhai Naoroji. Gokhale was a Moderate leader whom Gandhi regarded as his political guru.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-national-movement-113", "question": "Arrange these events in Gandhi's life in chronological order: 1. Writing of \"Hind Swaraj\" 2. Founding of the Natal Indian Congress 3. Setting up of Tolstoy Farm 4. Return to India", "options": ["2, 1, 3, 4", "1, 2, 3, 4", "2, 3, 1, 4", "2, 1, 4, 3"], "answer": 0, "explanation": "Natal Indian Congress 1894 → Hind Swaraj, written on the voyage from London to South Africa, 1909 → Tolstoy Farm near Johannesburg, with Hermann Kallenbach, 1910 → return to India, 9 January 1915.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-national-movement-114", "question": "Who was the first Indian woman to become President of the Indian National Congress, at the Kanpur session of 1925?", "options": ["Annie Besant", "Sarojini Naidu", "Nellie Sengupta", "Kamaladevi Chattopadhyay"], "answer": 1, "explanation": "Sarojini Naidu presided at Kanpur in 1925. Annie Besant (1917) was the first woman president but was Irish-born; Nellie Sengupta presided in 1933.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-national-movement-115", "question": "Mahatma Gandhi regarded which leader as his political guru?", "options": ["Bal Gangadhar Tilak", "Dadabhai Naoroji", "Gopal Krishna Gokhale", "Pherozeshah Mehta"], "answer": 2, "explanation": "Gandhi called Gokhale his political guru; on Gokhale's advice he spent his first year back in India (1915) travelling the country.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-national-movement-116", "question": "Gandhi's Sabarmati Ashram, from where the Dandi March began, is in:", "options": ["Wardha", "Ahmedabad", "Porbandar", "Rajkot"], "answer": 1, "explanation": "The ashram moved from Kochrab to the Sabarmati riverbank in Ahmedabad in 1917. Sevagram near Wardha became his base from 1936.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-national-movement-117", "question": "“Jana Gana Mana” was first sung at which Congress session?", "options": ["Calcutta, 1911", "Lucknow, 1916", "Calcutta, 1906", "Lahore, 1929"], "answer": 0, "explanation": "Tagore's song was first sung at the Calcutta session on 27 December 1911. Its first stanza was adopted as the National Anthem on 24 January 1950.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-national-movement-118", "question": "“Vande Mataram” was first sung at a session of the Congress in 1896 at Calcutta by:", "options": ["Bankim Chandra Chatterjee", "Aurobindo Ghose", "Surendranath Banerjea", "Rabindranath Tagore"], "answer": 3, "explanation": "Rabindranath Tagore sang it at the 1896 Calcutta session. Bankim Chandra wrote the song, which appears in his novel Anandamath (1882).", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-national-movement-119", "question": "The Bengali play “Neel Darpan” (1860), exposing the oppression of indigo cultivators, was written by:", "options": ["Dinabandhu Mitra", "Bankim Chandra Chatterjee", "Michael Madhusudan Dutt", "Girish Chandra Ghosh"], "answer": 0, "explanation": "Dinabandhu Mitra's play followed the Indigo Revolt of 1859–60. Its English translation, published by Rev. James Long, led to his conviction for libel.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-national-movement-120", "question": "Who became the youngest-ever Congress President, at the special Delhi session of 1923?", "options": ["Jawaharlal Nehru", "Subhas Chandra Bose", "Maulana Abul Kalam Azad", "Maulana Mohammad Ali"], "answer": 2, "explanation": "Abul Kalam Azad was about 35 when he presided over the special session of September 1923. Mohammad Ali presided at Kakinada later that year.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-national-movement-121", "question": "The National Planning Committee, with Jawaharlal Nehru as chairman, was set up in 1938 when the Congress President was:", "options": ["Rajendra Prasad", "Subhas Chandra Bose", "Vallabhbhai Patel", "Abul Kalam Azad"], "answer": 1, "explanation": "Bose, elected at the Haripura session (1938), set up the committee to plan India's industrial development.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-national-movement-122", "question": "The Communal Award of August 1932, which extended separate electorates to the Depressed Classes, was announced by:", "options": ["Lord Irwin", "Lord Willingdon", "Samuel Hoare", "Ramsay MacDonald"], "answer": 3, "explanation": "British Prime Minister Ramsay MacDonald announced the award. Gandhi's fast against it led to the Poona Pact in September 1932.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-national-movement-123", "question": "In the Alipore Bomb Case (1908–09), Aurobindo Ghose was defended and acquitted with the help of the lawyer:", "options": ["Motilal Nehru", "C. R. Das", "Bhulabhai Desai", "Tej Bahadur Sapru"], "answer": 1, "explanation": "Chittaranjan Das's defence won Aurobindo's acquittal; Barindra Ghose and others were convicted. Bhulabhai Desai later defended the INA officers.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-national-movement-124", "question": "Chandrashekhar Azad died in an encounter with the police in February 1931 at:", "options": ["Alfred Park, Allahabad", "Kakori, Lucknow", "Jallianwala Bagh, Amritsar", "Feroz Shah Kotla, Delhi"], "answer": 0, "explanation": "Azad was surrounded at Alfred Park (now Chandrashekhar Azad Park) in Allahabad and shot himself rather than be captured.", "difficulty": "hard", "source": "SSC CGL · State PSCs"},
  {"id": "history-national-movement-125", "question": "Pritilata Waddedar, a member of Surya Sen's group, died in 1932 after leading an attack on:", "options": ["The Writers' Building, Calcutta", "The Chittagong armoury", "The Pahartali European Club", "The Viceroy's train"], "answer": 2, "explanation": "Pritilata led the September 1932 raid on the Pahartali European Club in Chittagong and took cyanide to avoid arrest. The armoury raid was in April 1930.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-national-movement-126", "question": "The Bijolia peasant movement in Mewar against heavy cesses is chiefly associated with:", "options": ["Swami Sahajanand Saraswati", "Baba Ramchandra", "Vijay Singh Pathik", "N. G. Ranga"], "answer": 2, "explanation": "Vijay Singh Pathik led the long Bijolia struggle in Rajasthan from 1916. Baba Ramchandra organised Awadh's peasants and Sahajanand led the Bihar Kisan Sabha.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-national-movement-127", "question": "The Rampa rebellion of 1922–24 in the Godavari hill tracts was led by:", "options": ["Birsa Munda", "Alluri Sitarama Raju", "Komaram Bheem", "Tana Bhagat"], "answer": 1, "explanation": "Alluri Sitarama Raju led the tribal rising in the Andhra hills until he was killed in 1924. Birsa Munda's Ulgulan was in the Chotanagpur region (1899–1900).", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-national-movement-128", "question": "Who was the first Englishman to preside over the Indian National Congress, at its Allahabad session of 1888?", "options": ["A. O. Hume", "William Wedderburn", "George Yule", "Henry Cotton"], "answer": 2, "explanation": "George Yule presided in 1888. Wedderburn presided in 1889 and 1910, and Henry Cotton in 1904; Hume, the founder, never presided.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-national-movement-129", "question": "Who commanded the Rani of Jhansi Regiment, the women's unit of the Indian National Army?", "options": ["Captain Lakshmi Swaminathan", "Aruna Asaf Ali", "Usha Mehta", "Sucheta Kripalani"], "answer": 0, "explanation": "Dr Lakshmi Swaminathan (later Sahgal) led the regiment. Aruna Asaf Ali hoisted the flag at Gowalia Tank and Usha Mehta ran the secret radio in 1942.", "difficulty": "hard", "source": "SSC CGL · State PSCs"},
  {"id": "history-national-movement-130", "question": "In December 1928, Bhagat Singh and Rajguru shot the police officer J. P. Saunders in Lahore to avenge the death of:", "options": ["Jatin Das", "Lala Lajpat Rai", "Ram Prasad Bismil", "Ashfaqulla Khan"], "answer": 1, "explanation": "Lajpat Rai had died after the lathi charge on the anti-Simon Commission procession; the revolutionaries meant to target Superintendent James Scott but killed Saunders.", "difficulty": "hard", "source": "SSC CGL · State PSCs"},
  {"id": "history-national-movement-131", "question": "Who became the first Indian (elected) President of the Central Legislative Assembly in 1925?", "options": ["Motilal Nehru", "Madan Mohan Malaviya", "Vithalbhai Patel", "Bhulabhai Desai"], "answer": 2, "explanation": "Vithalbhai Patel, a Swarajist and elder brother of Vallabhbhai, was elected in 1925. Motilal Nehru led the Swaraj Party in the Assembly.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-national-movement-132", "question": "Match the parallel government set up during the Quit India Movement with its region: A. Prati Sarkar B. Jatiya Sarkar C. Chittu Pandey's national government — 1. Ballia (U.P.) 2. Satara (Maharashtra) 3. Tamluk (Midnapore, Bengal). Which option is correct?", "options": ["A-2, B-1, C-3", "A-3, B-2, C-1", "A-2, B-3, C-1", "A-1, B-3, C-2"], "answer": 2, "explanation": "The Prati Sarkar under Nana Patil functioned in Satara, the Tamralipta Jatiya Sarkar in Tamluk, and Chittu Pandey briefly took over Ballia in August 1942.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-national-movement-133", "question": "Match the Congress session with its president: A. Gaya, 1922 B. Ramgarh, 1940 C. Calcutta, 1917 D. Calcutta, 1928 — 1. Annie Besant 2. C. R. Das 3. Motilal Nehru 4. Abul Kalam Azad", "options": ["A-2, B-4, C-1, D-3", "A-3, B-4, C-1, D-2", "A-2, B-1, C-4, D-3", "A-2, B-4, C-3, D-1"], "answer": 0, "explanation": "C. R. Das presided at Gaya, Azad at Ramgarh, Annie Besant at Calcutta in 1917 and Motilal Nehru at Calcutta in 1928, where the Nehru Report was discussed.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-national-movement-134", "question": "Arrange in chronological order: 1. Communal Award 2. Poona Pact 3. Second Round Table Conference 4. Gandhi–Irwin Pact", "options": ["4, 3, 2, 1", "3, 4, 1, 2", "4, 1, 3, 2", "4, 3, 1, 2"], "answer": 3, "explanation": "Gandhi–Irwin Pact (March 1931), Second RTC (September–December 1931), Communal Award (August 1932) and Poona Pact (September 1932).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-national-movement-135", "question": "Arrange these uprisings in chronological order: 1. Rampa rebellion 2. Santhal hul 3. Birsa Munda's Ulgulan 4. Indigo revolt in Bengal", "options": ["2, 4, 3, 1", "4, 2, 3, 1", "2, 3, 4, 1", "2, 4, 1, 3"], "answer": 0, "explanation": "Santhal hul (1855–56), Indigo revolt (1859–60), Ulgulan (1899–1900) and Rampa (1922–24).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-national-movement-136", "question": "Consider the following statements: 1. The Madras session of the Congress (1927) passed a resolution declaring complete national independence to be its goal. 2. 26 January 1930 was observed across India as Purna Swaraj (Independence) Day. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. The 1927 resolution was moved by Jawaharlal Nehru; the Lahore session (1929) made Purna Swaraj the formal creed, leading to the 1930 observance.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-national-movement-137", "question": "Assertion (A): The Communal Award (1932) gave separate electorates to the Depressed Classes. Reason (R): Gandhi went on a fast unto death in Yerwada jail against this provision.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 1, "explanation": "Both are true, but R is a reaction to A, not its cause. The fast led to the Poona Pact, which replaced separate electorates with reserved seats in joint electorates.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-national-movement-138", "question": "How many of these statements about the Congress Socialist Party are correct? I. It was formed in 1934. II. Jayaprakash Narayan was its general secretary. III. Ram Manohar Lohia was among its leaders. IV. It was formed as a party outside the Congress, rival to it.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The CSP worked as a group within the Congress, with Acharya Narendra Dev, JP and Lohia among its leaders.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-national-movement-139", "question": "Assertion (A): The Nagpur session of the Congress (1920) reorganised the Provincial Congress Committees on a linguistic basis. Reason (R): The Nagpur session ratified the programme of non-cooperation.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 1, "explanation": "Both are true, but the linguistic reorganisation was meant to reach the masses in their own languages, not a result of ratifying non-cooperation. The session was presided over by C. Vijayaraghavachariar.", "difficulty": "very-hard", "source": "UPSC Prelims"},
];

export default questions;
